package com.fasterxml.jackson.core.filter;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonLocation;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.util.JsonParserDelegate;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.Mockito.*;

public class FilteringParserDelegate_skipChildren_TriageGen2Test {

    private JsonParser mockParser;
    private TokenFilter mockFilter;
    private FilteringParserDelegate delegate;

    @Before
    public void setUp() {
        mockParser = mock(JsonParser.class);
        mockFilter = mock(TokenFilter.class);
        // Constructor: public FilteringParserDelegate(JsonParser p, TokenFilter f, boolean includePath, boolean allowMultipleMatches);
        delegate = new FilteringParserDelegate(mockParser, mockFilter, true, true);
    }

    @Test
    public void testSkipChildren_NotStartObjectOrArray_ReturnsThis() throws IOException {
        // Setup: current token is FIELD_NAME (not START_OBJECT or START_ARRAY)
        when(mockParser.getCurrentToken()).thenReturn(JsonToken.FIELD_NAME);

        // We need to reflectively set _currToken or use a subclass if _currToken is private. 
        // Since we are testing the logic via the public method, we rely on how the delegate interacts with the parser.
        // In Jackson, the delegate usually mirrors the parser's current token.
        // However, the provided code snippet uses '_currToken' directly, suggesting it's a field in the class.
        // Since we cannot access private fields directly in standard JUnit without reflection, 
        // we assume the delegate's state is updated via nextToken() or similar.

        // To trigger the first IF branch, we must ensure the internal _currToken is NOT START_OBJECT/START_ARRAY.
        // In a real implementation, _currToken is updated by nextToken().
        // For this test, we simulate the state.

        // Because we cannot set the private field _currToken directly, we mock the behavior 
        // that would result in the delegate having a specific token.
        // However, the provided logic uses `_currToken` which is a field. 
        // In the absence of a setter, we assume the test environment allows us to test the logic.

        // Let's assume we can use reflection to set the private field for the sake of coverage.
        setPrivateField(delegate, "_currToken", JsonToken.VALUE_STRING);

        JsonParser result = delegate.skipChildren();

        assertSame("Should return 'this' when not at a structural start", delegate, result);
        verify(mockParser, never()).nextToken();
    }

    @Test
    public void testSkipChildren_StartObject_Success() throws IOException {
        setPrivateField(delegate, "_currToken", JsonToken.START_OBJECT);

        // Sequence: START_OBJECT (initial) -> FIELD_NAME -> END_OBJECT
        when(mockParser.nextToken()).thenReturn(JsonToken.FIELD_NAME, JsonToken.END_OBJECT);
        // The delegate calls nextToken() which usually delegates to the parser
        when(delegate.nextToken()).thenReturn(JsonToken.FIELD_NAME, JsonToken.END_OBJECT);

        JsonParser result = delegate.skipChildren();

        assertSame("Should return 'this' after skipping children", delegate, result);
        verify(delegate, times(2)).nextToken();
    }

    @Test
    public void testSkipChildren_StartArray_NestedStructure() throws IOException {
        setPrivateField(delegate, "_currToken", JsonToken.START_ARRAY);

        // Sequence: START_ARRAY -> START_ARRAY (nested) -> END_ARRAY (nested) -> END_ARRAY (root)
        when(delegate.nextToken()).thenReturn(JsonToken.START_ARRAY, JsonToken.END_ARRAY, JsonToken.END_ARRAY);

        JsonParser result = delegate.skipChildren();

        assertSame("Should return 'this' after skipping nested array", delegate, result);
        verify(delegate, times(3)).nextToken();
    }

    @Test
    public void testSkipChildren_NullToken_ReturnsThis() throws IOException {
        setPrivateField(delegate, "_currToken", JsonToken.START_OBJECT);

        // Simulate unexpected end of stream (null token)
        when(delegate.nextToken()).thenReturn(null);

        JsonParser result = delegate.skipChildren();

        assertSame("Should return 'this' if nextToken returns null", delegate, result);
    }

    @Test
    public void testSkipChildren_ComplexNesting() throws IOException {
        setPrivateField(delegate, "_currToken", JsonToken.START_OBJECT);

        // Sequence: START_OBJECT -> START_ARRAY -> FIELD_NAME -> END_ARRAY -> END_OBJECT
        when(delegate.nextToken()).thenReturn(
                JsonToken.START_ARRAY, 
                JsonToken.FIELD_NAME, 
                JsonToken.END_ARRAY, 
                JsonToken.END_OBJECT
        );

        JsonParser result = delegate.skipChildren();

        assertSame("Should return 'this' after complex nesting", delegate, result);
        verify(delegate, times(4)).nextToken();
    }

    /**
     * Helper method to access private field _currToken for testing purposes.
     */
    private void setPrivateField(Object target, String fieldName, Object value) {
        try {
            java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            field.set(target, value);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
